const slides=[...document.querySelectorAll('.slide')];let activeSlide=0;function showSlide(index){if(!slides.length)return;activeSlide=(index+slides.length)%slides.length;slides.forEach((slide,i)=>slide.classList.toggle('active',i===activeSlide))}document.querySelector('.slide-next')?.addEventListener('click',()=>showSlide(activeSlide+1));document.querySelector('.slide-prev')?.addEventListener('click',()=>showSlide(activeSlide-1));
